#!/usr/bin/env bash
set -u
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"; PY="${PYTHON:-python}"; DATA=data/generated/full_stratified_active_v1; OOD=data/generated/ood_protocols; cd "$ROOT" || exit 1
i=0
for k in 5 6; do
  for seed in 56 57 58; do gpu=$i; key="transient2_latentdim${k}_kw24_h750_s${seed}"; log="runs/phase2/e138_k${k}s${seed}_g${gpu}"; cmd="cd $ROOT; CUDA_VISIBLE_DEVICES=$gpu PYTHONPATH=src $PY scripts/blind_evaluate.py --checkpoint runs/phase2/$key/best.pt --data $DATA --evaluation-data $OOD --mapping-split validation --evaluation-split test --windows-per-mode 1000 --seed 13800 --device cuda:0 --ridge-alpha-grid 0.001 0.01 0.1 1 10 100 1000 10000 --ridge-cv-folds 5 --output runs/phase2/${key}_ood_protocols_blind_strict_e138_groupcv1se.json > ${log}.blind.log 2>&1"; for mapseed in 8989 9090; do cmd="$cmd && CUDA_VISIBLE_DEVICES=$gpu PYTHONPATH=src $PY scripts/train_dynamics_aware_map.py --checkpoint runs/phase2/$key/best.pt --data $DATA --device cuda:0 --seed $mapseed --width 256 --depth 4 --steps 20000 --field-weights 1 --learning-rate 0.0002 --batch-size 4096 --grad-clip 1 --include-voltage --mode voltage_clamp --jvp-epsilon 0.01 --field-target mapped_hh --state-gate-weights 1,100,1 --select-best --calibration-split trajectory --output runs/phase2/${key}_vc_trajcal_seed${mapseed}.json > ${log}.chart${mapseed}.log 2>&1"; done; cmd="$cmd; echo \$? > ${log}.exit"; tmux new-session -d -s "e138_k${k}s${seed}_g${gpu}" "bash -lc '$cmd'"; i=$((i+1)); done
done
tmux new-session -d -s e138_monitor "bash -lc 'cd $ROOT; while :; do n=0; bad=0; for f in runs/phase2/e138_k*s*_g*.exit; do test -f \"\$f\" || continue; n=\$((n+1)); test \"\$(tr -d \"[:space:]\" < \"\$f\")\" = 0 || bad=1; done; if test \$n -eq 6; then if test \$bad -eq 0; then msg=\"All jobs finished with exit code 0.\"; else msg=\"At least one job failed; check the exit codes and logs.\"; fi; tmux send-keys -t hh:0.0 -l \"\$msg\"; sleep 2; tmux send-keys -t hh:0.0 C-m; exit; fi; sleep 300; done'"
